#include <stdio.h>
#include <string.h>
#include <stdbool.h>

static const int days_in_month[12] = {31,28,31,30,31,30,31,31,30,31,30,31};

static bool is_leap_year(int year) {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

static int digit_value(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    return -1;
}

static bool validate_date(const char *s) {
    if (strlen(s) != 10) return false;
    if (s[4] != '-' || s[7] != '-') return false;
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (digit_value(s[i]) == -1) return false;
    }
    int year = digit_value(s[0])*1000 + digit_value(s[1])*100 + digit_value(s[2])*10 + digit_value(s[3]);
    int month = digit_value(s[5])*10 + digit_value(s[6]);
    int day = digit_value(s[8])*10 + digit_value(s[9]);
    if (month < 1 || month > 12) return false;
    int max_day = days_in_month[month-1];
    if (month == 2 && is_leap_year(year)) max_day = 29;
    if (day < 1 || day > max_day) return false;
    return true;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }
    if (validate_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");
    return 0;
}
